  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Meperidine, a small N-methylpiperidine analogue with a basic tertiary amine, has human oral bioavailability of 50–75%, directly supporting F≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Fenspiride, a spiro piperidine fused to an oxygen-containing ring, shows ~90% absolute oral bioavailability in healthy volunteers, closely matching the query's spiro ether scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "PF-592379, an N-alkyl piperidine/morpholine ether with a basic amine, was predicted to have >60% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Nicotine, a small basic N-methyl amine, has 44% oral bioavailability in humans despite ionization, showing that basic amines of this class can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Pentazocine, a related tertiary-amine opioid with an alkene, has mean oral bioavailability of 18% in healthy subjects, below the threshold; however, its phenolic OH and N-prenyl group create a first-pass conjugation liability absent in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F≥20%) because multiple close analogues with N-methylpiperidine or spiro ether scaffolds show human oral bioavailability of 44–90%; the only sub-20% analogue, pentazocine, differs by a phenolic conjugation liability and is outweighed by the stronger, more transferable high-F evidence.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the query molecule.",
    "Metabolic fate of the exocyclic alkene and tertiary amine is unquantified; first-pass extraction could lower F.",
    "Intestinal permeability was not directly measured; high basic pKa and low logD may reduce passive absorption, though small size and low TPSA may compensate.",
    "Pentazocine's low F in healthy subjects indicates that some related basic opioids can fall below 20%, but its phenol group is absent in the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

